using System;using System.Collections.Generic;using System.Linq;namespace Game.Runtime{internal sealed partial class GeneratedConfiguredDefinitionSource{
 internal static string NormalizeSpawnableKey(string value)=>BuildingDefinitionPrefabSystemHelper.NormalizeSpawnableKey(value); internal static bool RuntimeDefinitionMatchesId(RuntimeDefinition d,string value)=>BuildingDefinitionPrefabSystemHelper.RuntimeDefinitionMatchesId(d,value); readonly Dictionary<SourceUnitPrefab,BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry> requestEntries=new Dictionary<SourceUnitPrefab,BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry>();internal bool RequestMetadataKnown=>requestEntries.Count!=0;readonly List<RuntimeDefinition> generatedDefinitions=new List<RuntimeDefinition>();internal int ConfiguredSpawnableCount=>generatedDefinitions.Count;
 internal void BindGeneratedDefinitions(IReadOnlyList<RuntimeDefinition> definitions,bool sourceDomainComplete){if(!sourceDomainComplete||definitions==null||generatedDefinitions.Count!=0)throw new NotSupportedException("Complete source definitions bind once");foreach(var d in definitions){if(d==null||!d.SourceMetadataComplete||d.Prefab==null)throw new NotSupportedException("Actual authored definition/prefab identity required");generatedDefinitions.Add(d);}}
 internal bool TryGetConfiguredDefinition(SourceUnitPrefab prefab,out RuntimeDefinition d){d=generatedDefinitions.FirstOrDefault(x=>ReferenceEquals(x.Prefab,prefab));return d!=null;}
 internal bool TryGetConfiguredDefinition(int index,out RuntimeDefinition d){d=index>=0&&index<generatedDefinitions.Count?generatedDefinitions[index]:null;return d!=null;}
 internal bool TryResolveConfiguredSpawnablePrefab(string key,out SourceUnitPrefab p){var normalized=NormalizeSpawnableKey(key);p=generatedDefinitions.FirstOrDefault(x=>RuntimeDefinitionMatchesId(x,normalized))?.Prefab;return p!=null;}
 internal bool TryGetConfiguredSpawnable(SourceUnitPrefab prefab,out BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry entry){if(!TryGetConfiguredDefinition(prefab,out var d)){entry=default;return false;}entry=requestEntries.TryGetValue(prefab,out var known)?known:BuildConfiguredSpawnableEntry(d);return true;}
 internal bool TryGetConfiguredSpawnable(int index,out BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry entry){if(!TryGetConfiguredDefinition(index,out var d)){entry=default;return false;}return TryGetConfiguredSpawnable(d.Prefab,out entry);}
 internal void BindRequestMetadata(IReadOnlyList<SourceUnitPrefab> order,IReadOnlyDictionary<SourceUnitPrefab,BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry> entries){if(RequestMetadataKnown||order==null||entries==null||order.Count!=generatedDefinitions.Count||entries.Count!=order.Count)throw new InvalidOperationException("Complete configured request metadata binds once");var selected=new List<RuntimeDefinition>();var seen=new HashSet<SourceUnitPrefab>();foreach(var token in order){if(!seen.Add(token)||!entries.ContainsKey(token)||!TryGetConfiguredDefinition(token,out var d))throw new InvalidOperationException("Configured source identity mismatch");selected.Add(d);}generatedDefinitions.Clear();generatedDefinitions.AddRange(selected);foreach(var pair in entries)requestEntries.Add(pair.Key,pair.Value);}
 internal static BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry BuildConfiguredSpawnableEntry(RuntimeDefinition definition)
{if(definition==null)return default;return new BuildingUiCommandSystemHelper.ConfiguredSpawnableEntry(definition.DisplayName,definition.Description,definition.Prefab,true,20000);}
}}
